sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const fields = api.data.record.form.fields;
  const field= api.item.value.payload.journalFieldName;
  const formField = fields[field];
  return {  [formField.name] : formField};
}
